pub fn arccosh(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    // Input is assumed non-empty by the problem statement, but this also works for n == 0.
    let mut result: Vec<f32> = Vec::with_capacity(n);

    // Process sequentially by index, preserving order.
    for i in 0..n {
        // Invariant: after processing i elements, result has length i.
        debug_assert_eq!(result.len(), i);
        debug_assert!(result.len() <= n);

        let y = x[i].acosh(); // element-wise fixed unary transformation
        result.push(y);

        // After push: processed i+1 elements, result length is i+1.
        debug_assert_eq!(result.len(), i + 1);
    }

    debug_assert_eq!(result.len(), n);
    result
}